using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResource
{
    [McpServerResource(UriTemplate = "config://app/settings", Name = "App Settings",
        MimeType = "application/json"), Description("Returns current application configuration")]
    public static string GetAppSettings()
    {
        var config = new
        {
            Environment = "Production",
            MaxRetries = 3,
            TimeoutSeconds = 30,
            Features = new { DarkMode = true, BetaAccess = false }
        };

        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(UriTemplate = "config://app/version", Name = "App Version",
        MimeType = "text/plain"), Description("Returns the application version string")]
    public static string GetVersion() => "1.0.0-preview";
}

using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Validates a configuration key exists and returns its value")]
    public static string ValidateConfigKey(
        [Description("The configuration key to look up (e.g., 'MaxRetries')")] string key)
    {
        var knownKeys = new Dictionary<string, string>
        {
            ["Environment"] = "Production",
            ["MaxRetries"] = "3",
            ["TimeoutSeconds"] = "30"
        };

        return knownKeys.TryGetValue(key, out var value)
            ? $"Key '{key}' = {value}"
            : $"Key '{key}' not found in configuration.";
    }
}

